import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print(-1)
        return

    n = int(data[0].strip())

    if n == 0:
        print(0)
        return

    if len(data) < 1 + n:
        print(-1)
        return

    strings = []
    for i in range(1, 1 + n):
        strings.append(data[i].strip())

    max_length = 0
    for s in strings:
        if len(s) > max_length:
            max_length = len(s)

    print(max_length)

if __name__ == "__main__":
    main()
